 private function authorize(int $issuer,int $actor,string $kind,string $cap):void{$t=self::target($kind);$acl=new IssuerResourceAccess($this->db,$this->p);$acl->lockFinancialIdentity($issuer,$actor);if(!$acl->can($issuer,$actor,$t['feature'],'view')||!$acl->can($issuer,$actor,$t['feature'],$cap))throw new DomainException('company_operation_access_denied');}
