  return $this->tx(function()use($issuer,$actor,$kind,$id,$t):array{$this->authorize($issuer,$actor,$kind,'view');$r=$this->parent($issuer,$kind,$id);$publication=$this->rows('SELECT visible FROM '.$this->p.'company_portal_'.$kind.' WHERE issuer_id=? AND '.$t['field'].'=?',[$issuer,$id])[0]??[];$files=$this->rows('SELECT f.file_key,f.filename,COALESCE(v.visible,0) visible FROM '.$this->p.$t['files'].' f LEFT JOIN '.$this->p.'company_portal_'.$kind.'_files v ON v.issuer_id=f.issuer_id AND v.'.$t['field'].'=f.'.$t['field'].' AND v.file_key=f.file_key WHERE f.issuer_id=? AND f.'.$t['field'].'=? AND f.active=1'.($kind==='projects'?' AND f.task_id IS NULL':'').' ORDER BY f.created_at,f.file_key LIMIT 20',[$issuer,$id]);$replies=$kind==='tickets'?$this->rows('SELECT r.id,r.body,r.created_at,COALESCE(v.visible,0) visible FROM '.$this->p.'company_ticket_replies r LEFT JOIN '.$this->p.'company_portal_ticket_replies v ON v.issuer_id=r.issuer_id AND v.ticket_id=r.ticket_id AND v.reply_id=r.id WHERE r.issuer_id=? AND r.ticket_id=? AND '.NativeCompanyTicketVisibility::predicate($this->db,$this->p,'r.issuer_id','r.id',true).' ORDER BY r.id LIMIT 500',[$issuer,$id]):[];return ['visible'=>(bool)($publication['visible']??0),'eligible'=>$this->eligible($r,$kind),'private_client'=>$this->privateClient($issuer,(int)$r['client_id']),'files'=>$files,'replies'=>$replies];});
