   $this->authorize($issuer,$actor,$kind,'edit');$parent=$this->parent($issuer,$kind,$id);if($type==='reply')NativeCompanyTicketVisibility::assertReply($this->db,$this->p,$issuer,$child);$receipt=$this->rows('SELECT issuer_id,actor_id,kind,parent_id,input_hash FROM '.$this->p.'company_portal_operation_requests WHERE request_key=? FOR UPDATE',[$key])[0]??null;
