   $table='company_portal_'.$kind;$fields=['issuer_id'=>$issuer,$t['field']=>$id];$where='issuer_id=? AND '.$t['field'].'=?';$args=[$issuer,$id];
   if($type==='file'){if(!$this->rows('SELECT file_key FROM '.$this->p.$t['files'].' WHERE issuer_id=? AND '.$t['field'].'=? AND file_key=? AND active=1'.($kind==='projects'?' AND task_id IS NULL':'').' FOR UPDATE',[$issuer,$id,$child]))throw new DomainException('company_operation_access_denied');$table.='_files';$fields['file_key']=$child;$where.=' AND file_key=?';$args[]=$child;}
   elseif($type==='reply'){NativeCompanyTicketVisibility::assertReply($this->db,$this->p,$issuer,$child);if(!$this->rows('SELECT id FROM '.$this->p.'company_ticket_replies WHERE issuer_id=? AND ticket_id=? AND id=? FOR UPDATE',[$issuer,$id,$child]))throw new DomainException('company_operation_access_denied');$table='company_portal_ticket_replies';$fields['reply_id']=$child;$where.=' AND reply_id=?';$args[]=$child;}
   $now=gmdate('Y-m-d H:i:s');$exists=$this->rows('SELECT visible FROM '.$this->p.$table.' WHERE '.$where.' FOR UPDATE',$args);if($exists)IssuerStorage::query($this->db,'UPDATE '.$this->p.$table.' SET visible=?,actor_id=?,updated_at=? WHERE '.$where,array_merge([(int)$visible,$actor,$now],$args));else{$fields+=['visible'=>(int)$visible,'actor_id'=>$actor,'updated_at'=>$now];IssuerStorage::query($this->db,'INSERT INTO '.$this->p.$table.' (`'.implode('`,`',array_keys($fields)).'`) VALUES ('.implode(',',array_fill(0,count($fields),'?')).')',array_values($fields));}
   if(!$this->rows('SELECT visible FROM '.$this->p.$table.' WHERE '.$where.' AND visible=? AND actor_id=?',array_merge($args,[(int)$visible,$actor])))throw new RuntimeException('issuer_portal_operation_unconfirmed');
   IssuerStorage::query($this->db,'UPDATE '.$this->p.$t['parent'].' SET revision=revision+1,updated_at=? WHERE issuer_id=? AND id=? AND revision=?',[$now,$issuer,$id,$revision]);if((int)$this->parent($issuer,$kind,$id)['revision']!==$revision+1)throw new RuntimeException('issuer_portal_operation_unconfirmed');
   $this->audit($issuer,$actor,$id,'company_operation_portal_publication',['kind'=>$kind,'type'=>$type,'child'=>$child,'visible'=>$visible,'request_key'=>$key]);IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'company_portal_operation_requests(request_key,issuer_id,actor_id,kind,parent_id,input_hash,created_at) VALUES(?,?,?,?,?,?,?)',[$key,$issuer,$actor,$kind,$id,$hash,$now]);if(!$this->rows('SELECT request_key FROM '.$this->p.'company_portal_operation_requests WHERE request_key=? AND issuer_id=? AND actor_id=? AND input_hash=?',[$key,$issuer,$actor,$hash]))throw new RuntimeException('issuer_portal_operation_unconfirmed');$this->authorize($issuer,$actor,$kind,'edit');
  });
